syms s t

A = [-1 -0.5; 1 0];
B = [0.5 ; 0];
C = [1 0];
D = 0;
t1 = [0:0.05:10];

sys = ss(A,B,C,D);
[num, den] = ss2tf(A,B,C,D);
tf(num, den) %[output:07be18e3]
mf = inv(s*eye(1) - A) %[output:28f8ab10]
mt = ilaplace(mf, t) %[output:2238b9e1]

step(sys,t1); %[output:52553d4f]
impulse(sys, t1); %[output:7ba18b09]

ctb = det(ctrb(A,B)) %[output:9f4f38b5]
obs = det(obsv(A,C)) %[output:3043bbd5]

